from typing import Awaitable, Callable, Generic, Iterator, TypeVar

from fastapi import Depends, FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel

T = TypeVar("T")


class Reawaitable(Generic[T]):
    __sentinel = object()

    def __init__(self, awaitable):
        self.awaitable = awaitable
        self.result = self.__sentinel

    def __await__(self) -> Iterator[T]:
        if self.result is self.__sentinel:
            self.result = yield from self.awaitable.__await__()
        return self.result


def reawaitable(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return Reawaitable(func(*args, **kwargs))
    return wrapper


